  'products.subtitle': { fr: 'Catégories et produits (prix par magasin, langues, rupture), importés depuis l\'API TFBuddy — la base PWA en secours.', nl: 'Categorieën en producten (prijs per winkel, talen, uitverkocht), geïmporteerd uit de TFBuddy-API — de PWA-database als reserve.', en: 'Categories and products (per-store prices, languages, out-of-stock), imported from the TFBuddy API — the PWA database as fallback.', it: 'Categorie e prodotti (prezzi per negozio, lingue, esaurito), importati dall\'API TFBuddy — il database PWA come riserva.' },
  'seasons.subtitle': { fr: 'Définissez les saisons et fêtes (du → au) et les produits liés. Sert à cibler automatiquement les vidéos et animations de saison.', nl: 'Bepaal de seizoenen en feestdagen (van → tot) en de gekoppelde producten. Zo worden seizoensvideo\'s en -animaties automatisch gericht ingezet.', en: 'Define seasons and holidays (from → to) and their linked products. Used to automatically target seasonal videos and animations.', it: 'Definisci stagioni e festività (dal → al) e i prodotti collegati. Serve a mirare automaticamente video e animazioni stagionali.' },
  'planning.subtitle': { fr: '5 modèles de semaine réutilisables (A–E). Choisissez les magasins, remplissez chaque jour (matin / midi / après-midi), puis activez la semaine à diffuser.', nl: '5 herbruikbare weekmodellen (A–E). Kies de winkels, vul elke dag in (ochtend / middag / namiddag) en activeer dan de week die uitgezonden moet worden.', en: '5 reusable week templates (A–E). Pick the stores, fill in each day (morning / midday / afternoon), then activate the week to broadcast.', it: '5 modelli di settimana riutilizzabili (A–E). Scegli i negozi, compila ogni giorno (mattina / mezzogiorno / pomeriggio), poi attiva la settimana da trasmettere.' },
  'fleet.subtitle': { fr: 'État en direct des écrans, coordonnées et zones par magasin.', nl: 'Live status van de schermen, gegevens en zones per winkel.', en: 'Live status of screens, contact details and zones per store.', it: 'Stato in tempo reale degli schermi, recapiti e zone per negozio.' },

