  'bundles.notConfigured': { fr: 'Compte TFBuddy non configuré : ajoutez les secrets GitHub TFBUDDY_PHONE et TFBUDDY_PASSWORD (un compte qui a le droit MENU.BUNDLE.MANAGE), puis relancez la livraison.', nl: 'TFBuddy-account niet ingesteld: voeg de GitHub-secrets TFBUDDY_PHONE en TFBUDDY_PASSWORD toe (een account met het recht MENU.BUNDLE.MANAGE) en start de levering opnieuw.', en: 'TFBuddy account not configured: add the GitHub secrets TFBUDDY_PHONE and TFBUDDY_PASSWORD (an account with the MENU.BUNDLE.MANAGE right), then run the delivery again.', it: 'Account TFBuddy non configurato: aggiungi i secret GitHub TFBUDDY_PHONE e TFBUDDY_PASSWORD (un account con il diritto MENU.BUNDLE.MANAGE), poi rilancia la consegna.' },
