  'bundles.pick': { fr: '— Choisir un bundle —', nl: '— Kies een bundel —', en: '— Choose a bundle —', it: '— Scegli un bundle —' },
  'bundles.inactiveNote': { fr: 'Ce bundle n\'est pas actif dans TFBuddy : il ne passe pas à l\'écran.', nl: 'Deze bundel is niet actief in TFBuddy: hij verschijnt niet op het scherm.', en: 'This bundle is not active in TFBuddy: it does not play on screen.', it: 'Questo bundle non è attivo in TFBuddy: non passa sullo schermo.' },
  'bundles.noneYet': { fr: 'Aucun bundle TFBuddy synchronisé.', nl: 'Geen TFBuddy-bundel gesynchroniseerd.', en: 'No TFBuddy bundle synced.', it: 'Nessun bundle TFBuddy sincronizzato.' },
  'bundles.goSync': { fr: 'Synchroniser les bundles →', nl: 'Bundels synchroniseren →', en: 'Sync the bundles →', it: 'Sincronizza i bundle →' },
  'bundles.title': { fr: 'Bundles TFBuddy · {n}', nl: 'TFBuddy-bundels · {n}', en: 'TFBuddy bundles · {n}', it: 'Bundle TFBuddy · {n}' },
  'bundles.subtitle': { fr: 'Vos bundles, lus sur l\'API TFBuddy (comme le cockpit consultant) : prix du bundle, produits et quantités, magasins, jours et heures. Ils se modifient dans TFBuddy ; ici, vous choisissez lesquels diffuser.', nl: 'Uw bundels, gelezen via de TFBuddy-API (zoals de consultant-cockpit): bundelprijs, producten en aantallen, winkels, dagen en uren. U wijzigt ze in TFBuddy; hier kiest u welke u toont.', en: 'Your bundles, read from the TFBuddy API (like the consultant cockpit): bundle price, products and quantities, stores, days and hours. You edit them in TFBuddy; here you pick which ones to show.', it: 'I tuoi bundle, letti dall\'API TFBuddy (come il cockpit consulente): prezzo del bundle, prodotti e quantità, negozi, giorni e orari. Si modificano in TFBuddy; qui scegli quali trasmettere.' },
