  'bundles.syncing': { fr: 'Synchronisation…', nl: 'Synchroniseren…', en: 'Syncing…', it: 'Sincronizzazione…' },
  'bundles.voucher': { fr: 'sur bon d\'achat', nl: 'met waardebon', en: 'voucher only', it: 'solo con buono' },
  'bundles.missingProduct': { fr: 'Produit absent du catalogue de la régie', nl: 'Product ontbreekt in de catalogus van de console', en: 'Product missing from the console catalogue', it: 'Prodotto assente dal catalogo della console' },
  'bundles.imgPlaceholder': { fr: 'Visuel (optionnel) : URL ou chemin, ex. media/petit-dej.jpg', nl: 'Beeld (optioneel): URL of pad, bv. media/ontbijt.jpg', en: 'Visual (optional): URL or path, e.g. media/breakfast.jpg', it: 'Immagine (facoltativa): URL o percorso, es. media/colazione.jpg' },
  'bundles.create': { fr: '＋ Créer l\'élément', nl: '＋ Element maken', en: '＋ Create the element', it: '＋ Crea l\'elemento' },
  'bundles.emptyOff': { fr: 'Rien à afficher tant que le compte TFBuddy n\'est pas configuré.', nl: 'Niets te tonen zolang het TFBuddy-account niet is ingesteld.', en: 'Nothing to show until the TFBuddy account is configured.', it: 'Niente da mostrare finché l\'account TFBuddy non è configurato.' },
  'bundles.empty': { fr: 'Aucun bundle dans TFBuddy.', nl: 'Geen bundels in TFBuddy.', en: 'No bundles in TFBuddy.', it: 'Nessun bundle in TFBuddy.' },
  'bundles.footer': { fr: 'Synchro automatique toutes les 30 minutes. Un changement dans TFBuddy (prix, produits, créneaux) arrive sur les écrans sans republier ; un bundle n\'y passe que s\'il est ACTIF.', nl: 'Automatische synchronisatie elke 30 minuten. Een wijziging in TFBuddy (prijs, producten, tijdvakken) komt op de schermen zonder opnieuw te publiceren; een bundel verschijnt alleen als hij ACTIEF is.', en: 'Automatic sync every 30 minutes. A change in TFBuddy (price, products, time slots) reaches the screens without republishing; a bundle only plays when it is ACTIVE.', it: 'Sincronizzazione automatica ogni 30 minuti. Una modifica in TFBuddy (prezzo, prodotti, fasce orarie) arriva sugli schermi senza ripubblicare; un bundle passa solo se è ATTIVO.' },
  // -- traductions des écrans (Claude propose, la régie valide) --
  'crumb.translations': { fr: '{n} texte(s) · {p} à valider', nl: '{n} tekst(en) · {p} te valideren', en: '{n} text(s) · {p} to approve', it: '{n} testo/i · {p} da convalidare' },
  'tr.subtitle': { fr: 'Les écrans d\'un magasin flamand affichent ses textes en néerlandais : noms de produits et de catégories, titres et accroches, campagnes, badges de promotion, bundles. Claude propose les traductions manquantes ; rien n\'atteint un écran sans votre validation.', nl: 'De schermen van een Vlaamse winkel tonen de teksten in het Nederlands: product- en categorienamen, titels en slogans, campagnes, promotiebadges, bundels. Claude stelt de ontbrekende vertalingen voor; niets komt op een scherm zonder uw goedkeuring.', en: 'The screens of a Flemish store show their texts in Dutch: product and category names, titles and taglines, campaigns, promotion badges, bundles. Claude suggests the missing translations; nothing reaches a screen until you approve it.', it: 'Gli schermi di un negozio fiammingo mostrano i testi in olandese: nomi di prodotti e categorie, titoli e slogan, campagne, badge promozionali, bundle. Claude propone le traduzioni mancanti; nulla arriva su uno schermo senza la tua convalida.' },
  'tr.lang': { fr: 'Langue des écrans', nl: 'Schermtaal', en: 'Screen language', it: 'Lingua degli schermi' },
  'tr.propose': { fr: 'Proposer avec Claude · {n}', nl: 'Voorstellen met Claude · {n}', en: 'Suggest with Claude · {n}', it: 'Proponi con Claude · {n}' },
  'tr.proposing': { fr: 'Claude traduit… {d}/{n}', nl: 'Claude vertaalt… {d}/{n}', en: 'Claude is translating… {d}/{n}', it: 'Claude sta traducendo… {d}/{n}' },
  'tr.validateAll': { fr: '✓ Valider les propositions · {n}', nl: '✓ Voorstellen valideren · {n}', en: '✓ Approve suggestions · {n}', it: '✓ Convalida le proposte · {n}' },
  'tr.claudeReady': { fr: '● Claude ({model}) prêt : il propose, vous validez. Les propositions restent en attente tant que vous ne les avez pas validées.', nl: '● Claude ({model}) staat klaar: hij stelt voor, u valideert. Voorstellen blijven wachten tot u ze valideert.', en: '● Claude ({model}) is ready: it suggests, you approve. Suggestions wait until you approve them.', it: '● Claude ({model}) è pronto: propone, tu convalidi. Le proposte restano in attesa finché non le convalidi.' },
  'tr.claudeOff': { fr: '○ Clé API Anthropic absente : ajoutez le secret ANTHROPIC_API_KEY au dépôt (Settings → Secrets and variables → Actions), puis relancez la livraison. En attendant, vous pouvez saisir les traductions à la main.', nl: '○ Geen Anthropic-API-sleutel: voeg het geheim ANTHROPIC_API_KEY toe aan de repository (Settings → Secrets and variables → Actions) en start de levering opnieuw. Intussen kunt u de vertalingen met de hand invullen.', en: '○ No Anthropic API key: add the ANTHROPIC_API_KEY secret to the repository (Settings → Secrets and variables → Actions), then run the delivery again. Meanwhile you can type translations by hand.', it: '○ Chiave API Anthropic assente: aggiungi il segreto ANTHROPIC_API_KEY al repository (Settings → Secrets and variables → Actions), poi rilancia la consegna. Nel frattempo puoi inserire le traduzioni a mano.' },
  'tr.jobDone': { fr: 'Dernière proposition : {n} texte(s) en {s} s · {i} jetons lus, {o} écrits', nl: 'Laatste voorstel: {n} tekst(en) in {s} s · {i} tokens gelezen, {o} geschreven', en: 'Last run: {n} text(s) in {s} s · {i} tokens read, {o} written', it: 'Ultima proposta: {n} testo/i in {s} s · {i} token letti, {o} scritti' },
  'tr.jobErrors': { fr: '{n} lot(s) en erreur : {err}', nl: '{n} batch(es) mislukt: {err}', en: '{n} batch(es) failed: {err}', it: '{n} lotto/i in errore: {err}' },
