  'tr.noStores': { fr: 'Aucun magasin en {lang} pour l\'instant : la langue d\'écran se règle par magasin dans Réseau & supervision.', nl: 'Nog geen winkel in het {lang}: de schermtaal stelt u per winkel in onder Netwerk & toezicht.', en: 'No store in {lang} yet: the screen language is set per store in Network & monitoring.', it: 'Ancora nessun negozio in {lang}: la lingua degli schermi si imposta per negozio in Rete e supervisione.' },
