  'tr.emptyTodo': { fr: 'Tout est traduit et validé', nl: 'Alles is vertaald en gevalideerd', en: 'Everything is translated and approved', it: 'Tutto è tradotto e convalidato' },
  'tr.footer': { fr: 'Seules les traductions validées passent à l\'écran, et seulement tant que le texte français n\'a pas changé : un texte modifié redevient « à traduire ». Les noms donnés par l\'ERP restent prioritaires. Les écrans se mettent à jour d\'eux-mêmes, sans republier.', nl: 'Alleen gevalideerde vertalingen komen op het scherm, en alleen zolang de Franse tekst niet verandert: een gewijzigde tekst wordt weer « te vertalen ». Namen uit het ERP hebben voorrang. De schermen werken zichzelf bij, zonder opnieuw te publiceren.', en: 'Only approved translations reach the screens, and only while the French text is unchanged: an edited text goes back to « to translate ». Names from the ERP take priority. Screens update by themselves, without republishing.', it: 'Solo le traduzioni convalidate arrivano sugli schermi, e solo finché il testo francese non cambia: un testo modificato torna « da tradurre ». I nomi dell\'ERP hanno la priorità. Gli schermi si aggiornano da soli, senza ripubblicare.' },
  'tr.saved': { fr: 'Traduction enregistrée — elle passe à l\'écran', nl: 'Vertaling opgeslagen — ze komt op het scherm', en: 'Translation saved — it goes on screen', it: 'Traduzione salvata — va sullo schermo' },
