  'tfb.editorTitle': { fr: 'Promotion TFBuddy suivie', nl: 'Gevolgde TFBuddy-promotie', en: 'Linked TFBuddy promotion', it: 'Promozione TFBuddy collegata' },
  'tfb.pickNone': { fr: '— Aucune : offre saisie à la main —', nl: '— Geen: aanbod met de hand ingevuld —', en: '— None: offer typed by hand —', it: '— Nessuna: offerta inserita a mano —' },
  'tfb.inactiveNote': { fr: 'Cette promotion n\'est pas active dans TFBuddy : elle ne passe pas à l\'écran.', nl: 'Deze promotie is niet actief in TFBuddy: ze verschijnt niet op het scherm.', en: 'This promotion is not active in TFBuddy: it does not play on screen.', it: 'Questa promozione non è attiva in TFBuddy: non passa sullo schermo.' },
  'tfb.editorHelp': { fr: 'Reliée, la promotion passe à ses jours et heures, dans ses magasins, entre ses dates. Sa mécanique s\'affiche en sous-titre (sauf texte saisi) et, pour une remise, le prix remisé « au lieu de ».', nl: 'Gekoppeld verschijnt de promotie op haar dagen en uren, in haar winkels, tussen haar data. Het mechanisme staat in de ondertitel (tenzij u zelf tekst invult) en bij een korting de prijs « i.p.v. ».', en: 'Linked, the promotion plays on its days and hours, in its stores, between its dates. Its mechanism shows as the subtitle (unless you type one) and, for a discount, the reduced price “instead of”.', it: 'Collegata, la promozione passa nei suoi giorni e orari, nei suoi negozi, tra le sue date. La meccanica appare come sottotitolo (salvo testo inserito) e, per uno sconto, il prezzo scontato « invece di ».' },
  'tfb.editorNone': { fr: 'Aucune promotion TFBuddy synchronisée.', nl: 'Geen TFBuddy-promotie gesynchroniseerd.', en: 'No TFBuddy promotion synced.', it: 'Nessuna promozione TFBuddy sincronizzata.' },
  'tfb.pointerTitle': { fr: 'Promotions TFBuddy · {n}', nl: 'TFBuddy-promoties · {n}', en: 'TFBuddy promotions · {n}', it: 'Promozioni TFBuddy · {n}' },
  'tfb.pointerText': { fr: 'Bundles, « X achetés = Y offert », promotions de quantité, remises programmées et bons d\'achat sont lus sur l\'API TFBuddy et rangés dans Promotions.', nl: 'Bundels, « X gekocht = Y gratis », hoeveelheidspromoties, geplande kortingen en waardebonnen worden via de TFBuddy-API gelezen en staan in Promoties.', en: 'Bundles, “buy X, get Y”, quantity promotions, scheduled discounts and vouchers are read through the TFBuddy API and listed in Promotions.', it: 'Bundle, « compri X = Y in omaggio », promozioni a quantità, sconti programmati e buoni sono letti tramite l\'API TFBuddy e raccolti in Promozioni.' },
  'tfb.title': { fr: 'Promotions TFBuddy · {n}', nl: 'TFBuddy-promoties · {n}', en: 'TFBuddy promotions · {n}', it: 'Promozioni TFBuddy · {n}' },
  'tfb.empty': { fr: 'Aucune promotion dans TFBuddy.', nl: 'Geen promoties in TFBuddy.', en: 'No promotions in TFBuddy.', it: 'Nessuna promozione in TFBuddy.' },
  'tfb.footer': { fr: 'Synchro automatique toutes les 30 minutes. Un changement dans TFBuddy arrive sur les écrans sans republier ; une promotion n\'y passe que si elle est ACTIVE, dans ses magasins, à ses jours et heures, entre ses dates.', nl: 'Automatische synchronisatie elke 30 minuten. Een wijziging in TFBuddy komt op de schermen zonder opnieuw te publiceren; een promotie verschijnt alleen als ze ACTIEF is, in haar winkels, op haar dagen en uren, tussen haar data.', en: 'Automatic sync every 30 minutes. A change in TFBuddy reaches the screens without republishing; a promotion only plays when it is ACTIVE, in its stores, on its days and hours, between its dates.', it: 'Sincronizzazione automatica ogni 30 minuti. Una modifica in TFBuddy arriva sugli schermi senza ripubblicare; una promozione passa solo se è ATTIVA, nei suoi negozi, nei suoi giorni e orari, tra le sue date.' },
  'tfb.goPromotions': { fr: 'Voir dans Promotions →', nl: 'Bekijken in Promoties →', en: 'See in Promotions →', it: 'Vedi in Promozioni →' },
  'crumb.tfbPromos': { fr: '{n} promotion(s) TFBuddy', nl: '{n} TFBuddy-promotie(s)', en: '{n} TFBuddy promotion(s)', it: '{n} promozione/i TFBuddy' },
  'badges.title': { fr: 'Style des badges', nl: 'Stijl van de badges', en: 'Badge style', it: 'Stile dei badge' },
  'badges.subtitle': { fr: 'Chaque famille de promotions TFBuddy s\'habille d\'un style : son icône, sa couleur et son libellé sur le badge à l\'écran. Un changement ici arrive sur tous les écrans, sans republier.', nl: 'Elke familie TFBuddy-promoties krijgt een stijl: het icoon, de kleur en het label van de badge op het scherm. Een wijziging hier komt op alle schermen, zonder opnieuw te publiceren.', en: 'Each TFBuddy promotion family wears a style: the icon, colour and label of its badge on screen. A change here reaches every screen, without republishing.', it: 'Ogni famiglia di promozioni TFBuddy veste uno stile: l\'icona, il colore e l\'etichetta del badge sullo schermo. Una modifica qui arriva su tutti gli schermi, senza ripubblicare.' },
