  'badges.editorFollows': { fr: 'Badge de la famille « {fam} » : il suit le style choisi dans Promotions.', nl: 'Badge van de familie « {fam} »: volgt de stijl gekozen in Promoties.', en: 'Badge of the “{fam}” family: it follows the style chosen in Promotions.', it: 'Badge della famiglia « {fam} »: segue lo stile scelto in Promozioni.' },
  'badges.editorChange': { fr: 'Changer le style', nl: 'Stijl wijzigen', en: 'Change the style', it: 'Cambia lo stile' },
  'badges.editorManual': { fr: 'Offre saisie à la main : choisissez son style de badge. Renseignez l\'accroche dans « Nom du module » et le détail dans « Sous-titre ».', nl: 'Met de hand ingevuld aanbod: kies de stijl van de badge. Vul de slogan in bij « Naam van de module » en het detail bij « Ondertitel ».', en: 'Offer typed by hand: choose its badge style. Put the hook in “Module name” and the detail in “Subtitle”.', it: 'Offerta inserita a mano: scegli lo stile del badge. Inserisci lo slogan in « Nome del modulo » e il dettaglio in « Sottotitolo ».' },
  'badges.editorStyles': { fr: 'Gérer les styles', nl: 'Stijlen beheren', en: 'Manage styles', it: 'Gestisci gli stili' },
  'styles.title': { fr: 'Styles de badge · {n}', nl: 'Badgestijlen · {n}', en: 'Badge styles · {n}', it: 'Stili di badge · {n}' },
  'styles.subtitle': { fr: 'Icône, libellé et couleur. Ils habillent les familles TFBuddy ci-dessus et les offres saisies à la main (ex. vente flash).', nl: 'Icoon, label en kleur. Ze kleden de TFBuddy-families hierboven en de met de hand ingevulde aanbiedingen (bv. flashverkoop).', en: 'Icon, label and colour. They dress the TFBuddy families above and offers typed by hand (e.g. flash sale).', it: 'Icona, etichetta e colore. Vestono le famiglie TFBuddy qui sopra e le offerte inserite a mano (es. vendita lampo).' },
