  'styles.manual': { fr: 'Offres saisies à la main uniquement', nl: 'Alleen met de hand ingevulde aanbiedingen', en: 'Offers typed by hand only', it: 'Solo offerte inserite a mano' },
  'styles.empty': { fr: 'Aucun style. « + Ajouter un style » pour en créer un.', nl: 'Geen stijl. « + Stijl toevoegen » om er een te maken.', en: 'No style. “+ Add a style” to create one.', it: 'Nessuno stile. « + Aggiungi uno stile » per crearne uno.' },
  'styles.namePh': { fr: 'Libellé (ex. Happy hour)', nl: 'Label (bv. Happy hour)', en: 'Label (e.g. Happy hour)', it: 'Etichetta (es. Happy hour)' },
