  'styles.del': { fr: 'Supprimer ce style', nl: 'Deze stijl verwijderen', en: 'Delete this style', it: 'Elimina questo stile' },
  'styles.on': { fr: 'Actif — proposé pour les offres saisies à la main', nl: 'Actief — voorgesteld voor met de hand ingevulde aanbiedingen', en: 'Active — offered for offers typed by hand', it: 'Attivo — proposto per le offerte inserite a mano' },
  'styles.off': { fr: 'Inactif — masqué du choix (garde les familles qu\'il habille)', nl: 'Inactief — verborgen uit de keuze (blijft de families kleden)', en: 'Inactive — hidden from the choice (still dresses its families)', it: 'Inattivo — nascosto dalla scelta (continua a vestire le sue famiglie)' },
  'styles.inactive': { fr: 'inactif', nl: 'inactief', en: 'inactive', it: 'inattivo' },
  'styles.footer': { fr: 'Supprimer un style ne casse rien : les éléments qui le portaient retombent sur un badge neutre « Offre », et les familles qu\'il habillait sur leur badge de repli.', nl: 'Een stijl verwijderen breekt niets: de elementen die hem droegen vallen terug op een neutrale badge « Aanbod », de families die hij kleedde op hun standaardbadge.', en: 'Deleting a style breaks nothing: elements that wore it fall back to a neutral “Offer” badge, and the families it dressed to their fallback badge.', it: 'Eliminare uno stile non rompe nulla: gli elementi che lo portavano ripiegano su un badge neutro « Offerta », e le famiglie che vestiva sul loro badge di riserva.' },
  'styles.delUsed': { fr: '{n} élément(s) portent « {name} ».', nl: '{n} element(en) dragen « {name} ».', en: '{n} element(s) wear “{name}”.', it: '{n} elemento/i portano « {name} ».' },
  'styles.delDresses': { fr: 'Il habille : {list} — elles reprendront leur badge de repli.', nl: 'Hij kleedt: {list} — die krijgen hun standaardbadge terug.', en: 'It dresses: {list} — they will go back to their fallback badge.', it: 'Veste: {list} — torneranno al loro badge di riserva.' },
  'styles.delConfirm': { fr: 'Supprimer quand même ce style ?', nl: 'Deze stijl toch verwijderen?', en: 'Delete this style anyway?', it: 'Eliminare comunque questo stile?' },
